        secret_key = f.read().strip()

    task_names = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            task_names.append(line)

    if not task_names:
        return

    task_start_times = []
    rate_limit = 1.0
    last_three_start_times = []

