        cache_file = os.path.join(cache_dir, f"{name}.cache")
        cmd_file = os.path.join(cache_dir, f"{name}.cmd")

        if os.path.exists(cache_file):
            with open(cache_file, 'r') as f:
                cached_data = f.read().strip()
                if cached_data:
                    value, stored_tag = cached_data.split('\t', 1)
                    recomputed_tag = compute_tag(value, secret_key)
                    if recomputed_tag == stored_tag:
                        print(value)
                        continue
                    else:
                        print(f"TAMPERED {name}")
                        sys.exit(2)
        else:
            if os.path.exists(cmd_file):
                with open(cmd_file, 'r') as f:
                    cmd = f.read().strip()
                    if not cmd:
                        print(f"Error: {cmd_file} is empty", file=sys.stderr)
                        sys.exit(1)
            else:
                print(f"Error: {cmd_file} does not exist", file=sys.stderr)
                sys.exit(1)

        start_time = time.time()
        task_start_times.append(start_time)
        last_three_start_times = task_start_times[-3:] if len(task_start_times) >= 3 else last_three_start_times + [start_time]

        if len(task_start_times) > 3:
            earliest_start = last_three_start_times[0]
            if start_time - earliest_start < rate_limit:
                time.sleep(rate_limit - (start_time - earliest_start))

        try:
            result = os.popen(cmd).read()
