import os
import sys
import time
import hashlib
from datetime import datetime, timedelta

def compute_tag(name, value, key):
    data = f"{name}{value}{key}".encode('utf-8')
    return hashlib.sha256(data).hexdigest()

def validate_cache(cache_dir, name, cache_file, key_file):
    with open(key_file, 'r') as kf:
        key = kf.read().strip()
    with open(cache_file, 'r') as cf:
        content = cf.read().strip()
    parts = content.split('\n')
    if len(parts) < 3:
        return False
    stored_name, stored_value, stored_tag = parts[0], parts[1], parts[2]
    if stored_name != name or stored_value != parts[1]:
        return False
    computed_tag = compute_tag(name, stored_value, key)
    return stored_tag == computed_tag

def run_command(cache_dir, name):
    cmd_file = os.path.join(cache_dir, f"{name}.cmd")
    if not os.path.exists(cmd_file):
        return None
    with open(cmd_file, 'r') as cf:
        cmd = cf.read().strip()
    start_time = time.time()
    try:
        result = os.popen(cmd).read()
        end_time = time.time()
        duration = end_time - start_time
        if duration > 1.0:
            print(f"TASK RATE LIMIT VIOLATION: {name} (duration: {duration:.2f}s)", file=sys.stderr)
            return None
        return result.strip()
    except Exception as e:
        print(f"ERROR RUNNING COMMAND: {name} - {str(e)}", file=sys.stderr)
        return None

def main():
    if len(sys.argv) != 3:
        print("Usage: python taskcache.py <cache_dir> <key_file>", file=sys.stderr)
        sys.exit(1)

    cache_dir = sys.argv[1]
    key_file = sys.argv[2]
    task_names = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            task_names.append(line)

    task_start_times = []
    for name in task_names:
        cache_file = os.path.join(cache_dir, f"{name}.cache")
        cmd_file = os.path.join(cache_dir, f"{name}.cmd")

        if os.path.exists(cache_file):
            if validate_cache(cache_dir, name, cache_file, key_file):
                with open(cache_file, 'r') as cf:
                    content = cf.read().strip()
                parts = content.split('\n')
                print(parts[1], end='\n')
                continue
            else:
                print(f"TAMPERED {name}", file=sys.stderr)
                sys.exit(2)
        else:
            if len(task_start_times) >= 3:
                oldest_start = task_start_times[0]
                if time.time() - oldest_start < 1.0:
                    time.sleep(1.0 - (time.time() - oldest_start))
                    task_start_times.pop(0)
            task_start_times.append(time.time())
            value = run_command(cache_dir, name)
            if value is None:
                continue
            tag = compute_tag(name, value, key_file)
            with open(cache_file, 'w') as cf:
                cf.write(f"{name}\n{value}\n{tag}\n")
            print(value, end='\n')

if __name__ == "__main__":
    main()
